// The Worker's entry (wrangler `main`) for an app with Vercel Cron jobs.
// @opennextjs/cloudflare generates a worker that exports `fetch`; this reuses
// that handler and adds the `scheduled` handler the Cron Trigger calls
// (https://opennext.js.org/cloudflare/howtos/custom-worker).
// @ts-ignore .open-next/worker.js is generated by the build
import handler from "./.open-next/worker.js";
import { makeScheduled } from "./lib/cron/scheduled";

const worker = {
  fetch: handler.fetch,
  scheduled: makeScheduled(handler.fetch),
};

export default worker;
